import React, { useState } from "react";
import ProductContext from "./product-context";

const ProductProvider = (props) => {
  const [openProduct, setOpenProduct] = useState(false);
  const [selectedItem, setSelectedItem] = useState([]);

  const productHandler = () => {
    setOpenProduct(!openProduct); // Toggle the state
  };

  // const showProduct = (item) => {
  //  // setSelectedItem([item]);
  //   setSelectedItem([...selectedItem, item]);
  //   setOpenProduct(true); // Ensure the product is open when selected
  //  // console.log(item);
  // };
  // const showProduct = (item) => {
  //   // Check if the item with the same id is already selected
  //   const itemExists = selectedItem.some((selected) => selected.id === item.id);

  //   // If the item doesn't exist, append it to the selectedItem array
  //   if (!itemExists) {
  //     setSelectedItem([...selectedItem, item]);
  //     setOpenProduct(true); // Ensure the product is open when selected
  //   }
  // };

  const showProduct = (item) => {
    const itemExists = selectedItem.find((selected) => selected.id === item.id);

    if (itemExists) {
      const updatedItems = selectedItem.map((selected) =>
        selected.id === item.id ? { ...selected, ...item } : selected
      );
      setSelectedItem(updatedItems);
    } else {
      setSelectedItem([...selectedItem, item]);
      setOpenProduct(true);
    }
  };
  // adding for button   
  const clearSelectedItems = () => {
    setSelectedItem([]); // Clear all selected items
  };


  const productContext = {
    openProduct,
    selectedItem,
    addItem: showProduct,
    productHandler: productHandler,
    clearSelectedItems,
    setSelectedItem
  };

  return (
    <ProductContext.Provider value={productContext}>
      {props.children}
    </ProductContext.Provider>
  );
};

export default ProductProvider;
